SQL_STMT_U.val:
SELECT rf.customer_id, c.name, rf.year_month, rf.sales_slip_count, rf.payment_slip_count, rf.previous_balance, rf.standard_sales_amount, rf.standard_return_amount, rf.standard_discount_amount, rf.standard_tax_amount, rf.reduced_sales_amount, rf.reduced_return_amount, rf.reduced_discount_amount, rf.reduced_tax_amount, rf.payment_amount, rf.current_balance,
SUM(COALESCE(rf.previous_balance,0)) OVER () AS total_previous_balance, SUM(COALESCE(rf.reduced_sales_amount,0) + COALESCE(rf.standard_sales_amount,0)) OVER () AS total_sales, SUM(COALESCE(rf.reduced_return_amount,0) + COALESCE(rf.standard_return_amount,0)) OVER () AS total_returns, SUM(COALESCE(rf.reduced_discount_amount,0) + COALESCE(rf.standard_discount_amount,0)) OVER () AS total_discounts, SUM(COALESCE(rf.reduced_tax_amount,0) + COALESCE(rf.standard_tax_amount,0)) OVER () AS total_tax, SUM(COALESCE(rf.payment_amount,0)) OVER () AS total_payments, SUM(COALESCE(rf.current_balance,0)) OVER () AS total_current_balance
FROM receivables_file AS rf LEFT JOIN customer AS c ON c.id = rf.customer_id WHERE rf.year_month = ':1' AND ( (:2 = 0 AND :3 = 0) OR (rf.customer_id BETWEEN :2 AND :3) ); -- AND c.branch_type IN (0,1);
